"""One bounded completed cut; accepted/running attempts retain distinct status."""
def append_wonly_exposure(inputs, paths, root, findings, observations, reference):
    rows=[('wonly','research.gv53.earlyload.wonly.fixed.01','gv53_earlyload_wonly_v1','VALID_GAIN_VS_PARENT_MIXED_VS_WX','W-only parent-minus-option paired+.096000731us,29W19L; versus WX−.031999312us. Parent−WX+.144000165us. WO F1before+1.183999702/after+.512000173us; WX+.064000487/−.607999042us, parentdrift−.671999529us. All three native/current-output/cleanup gates pass; oneWbank/8Xfixtures, no policy/official gain or pure fixed-X causal isolation.'),
      ('escape_exposure','research.rq.pooler32.escape.exposure.01','rq_pooler32_escape_exposure_v1','VALID_NO_GAIN_NOT_EXPOSED_DIAGNOSTIC','Exact5151/KS4:1024lists/4559records,max11/cap32; zero subsequent32-window refills. Current lookahead version parked unrun; initialLDG is a different path. No speed measurement or family rejection.'),
      ('xprefetch_check','38821b954fb14978','gv_unpool16_xprefetch_choice_v1','OFFICIAL_CHECK_VALID_WHOLE_LOSS_REFINE','CHECK9/9 at3225.130858482905us, REFINE; actual unpoolerM16 Xprefetch selected, same-prepare tuning+.095999800us. M1parent/M8earlyload selected. Whole score loses; selection/tuning/local gain and crossjob official transfer remain separate.'),
      ('qkv_full_cpu','CPU.gv_qkv_xprefetch_v1','gv_qkv_xprefetch_v1','CPU_SPILL_COUNTEREVIDENCE_NOT_GPU_MEASURED','Full X prefetch operand/native control proofs pass;64→63regs but32Bstack/48Bspill stores+48Bloads.1152→1168instructions. GPU gain unknown; preserve version and test bounded spill tradeoff separately.'),
      ('qkv_half_cpu','CPU.gv_qkv_half_xprefetch_v1','gv_qkv_half_xprefetch_v1','CPU_SPILL_COUNTEREVIDENCE_NOT_GPU_MEASURED','Half X revision still32Bstack/56Bspill stores+100Bloads,64regs;1152→1184instructions. Source/current operand identity passes; GPU gain unknown. Resource failure does not reject family; separate tradeoff running outside this completed cut.')]
    for key,attempt,version,classification,finding in rows:
        findings.append({'id':attempt,'immutable_id':'improvement.'+attempt,'classification':classification,'currently_included':'Historical scoped evidence; best incumbent unchanged','scope':'Projection only; completed measurements and CPU codegen evidence distinguished','finding':finding,'verification':'Frozen own analysis/source evidence; no delivered artifacts rewritten','stacked_versions':[version],'stack_tested_jobs':[attempt] if key in ('wonly','escape_exposure') else [],'score_tested_jobs':[attempt] if key=='xprefetch_check' else [],'missing_reason':'No causal/additive shipping gain beyond actual scoped evidence','next_action':'Threeway official accepted pending; QKV bounded tradeoff running separately; reopen dormant lookahead only on actual exposure','evidence':[reference(root,paths[key])]})
    data=inputs['wonly'];attempt=data['job_id'];evidence=reference(root,paths['wonly'])
    for contrast,t in data['contrasts'].items():
        bracket=data['F1']['brackets'].get('W_only' if contrast=='parent_minus_W_only' else 'W_X') if contrast.startswith('parent_') else None
        base={'attempt_id':attempt,'version':'gv53_earlyload_wonly_v1','control':contrast.split('_minus_')[0],'hardware':'H100','performance_admitted':True,'validity':'VALID_FIXED_THREE_ARM','shipping_gain':False,'evidence':evidence}
        observations.append(dict(base,observation_id='paired.'+attempt+'.'+contrast+'.summary',shape=contrast+'.summary',gain_us=t['paired_median_us'],F1_gain_us=bracket['endpoint_average_minus_arm_us'] if bracket else None,wins=t['wins_ties_losses'][0],ties=t['wins_ties_losses'][1],losses=t['wins_ties_losses'][2],pairs=48,observation_scope='Three-arm fixed M8;48triples share8Xfixtures; no independence/official inference',paired_mean_gain_us=t['paired_mean_us'],paired_control_first_gain_us=t['left_first_median_us'],paired_new_first_gain_us=t['right_first_median_us'],F1_before_gain_us=bracket['parent_before_minus_arm_us'] if bracket else None,F1_after_gain_us=bracket['parent_after_minus_arm_us'] if bracket else None))
        for i,g in enumerate(t['all_48_signed_us']):
            observations.append(dict(base,observation_id='paired.'+attempt+'.'+contrast+'.round'+str(i),shape=contrast+'.round'+str(i),gain_us=g,F1_gain_us=None,wins=int(g>0),ties=int(g==0),losses=int(g<0),pairs=1,observation_scope='One signed contrast from shared triple; not independent shipping evidence'))
